fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Create result vector with the same length
    let mut result = Vec::with_capacity(a.len());
    
    // Compare corresponding elements
    for i in 0..a.len() {
        // Convert i8 to i32 for comparison to avoid overflow issues
        result.push((a[i] as i32) > (b[i] as i32));
    }
    
    result
}